const listNotificationProviders = `-- name: ListNotificationProviders :many
SELECT id, type, name, config_json, secret_id, created_at, updated_at FROM notification_providers ORDER BY name
`

func (q *Queries) ListNotificationProviders(ctx context.Context) ([]NotificationProvider, error) {
	rows, err := q.db.QueryContext(ctx, listNotificationProviders)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []NotificationProvider{}
	for rows.Next() {
		var i NotificationProvider
		if err := rows.Scan(
			&i.ID,
			&i.Type,
			&i.Name,
			&i.ConfigJson,
			&i.SecretID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

